import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define BM 32
#define BN 32
#define BK 32

__global__ void cute_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K)
{
    __shared__ float As[BM][BK];
    __shared__ float Bs[BK][BN];

    // Build cute tensors over global memory for A (M x K), B (K x N), C (M x N)
    Tensor gA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{}));
    Tensor gB = make_tensor(make_gmem_ptr(B), make_shape(K, N), make_stride(N, Int<1>{}));
    Tensor gC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{}));

    int row = blockIdx.y * BM + threadIdx.y;
    int col = blockIdx.x * BN + threadIdx.x;

    float acc = 0.f;

    int numTiles = (K + BK - 1) / BK;
    for (int t = 0; t < numTiles; ++t) {
        int kA = t * BK + threadIdx.x;
        int kB = t * BK + threadIdx.y;

        As[threadIdx.y][threadIdx.x] = (row < M && kA < K) ? gA(row, kA) : 0.f;
        Bs[threadIdx.y][threadIdx.x] = (kB < K && col < N) ? gB(kB, col) : 0.f;

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < BK; ++k) {
            acc += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        gC(row, col) = acc;
    }
}

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");

    int M = (int)A.size(0);
    int K = (int)A.size(1);
    int N = (int)B.size(1);
    TORCH_CHECK((int)B.size(0) == K, "B.size(0) must equal A.size(1)");

    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    auto C   = torch::empty({M, N}, A.options());

    dim3 block(BN, BM);
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_matmul_kernel<<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE matmul launch failed");
    return C;
}
"""

cute_ext = load_inline(
    name="cute_matmul_tall_skinny_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A, B)

